const updatePostScreening = `-- name: UpdatePostScreening :one
UPDATE content.posts
SET status = $1, screen_reason = $2, ai_label = $3, ai_score = $4,
    model_version = $5, flag_rule = $6, ai_sentences = $7, needs_rescan = false,
    status_changed_at = CASE WHEN status = $1 THEN status_changed_at ELSE now() END
WHERE id = $8 AND needs_rescan
RETURNING id, channel_id, author_id, official, title, body, search_text, status, pinned, edited, comment_count, official_replied, screen_reason, ai_label, ai_score, model_version, flag_rule, ai_sentences, needs_rescan, created_at, updated_at, status_changed_at
`

type UpdatePostScreeningParams struct {
	Status       string
	ScreenReason *string
	AiLabel      *string
	AiScore      *float32
	ModelVersion *string
	FlagRule     *int32
	AiSentences  json.RawMessage
	ID           uuid.UUID
}

// Kết quả quét lại sau sự cố; giữ cờ edited
func (q *Queries) UpdatePostScreening(ctx context.Context, arg UpdatePostScreeningParams) (ContentPost, error) {
	row := q.db.QueryRow(ctx, updatePostScreening,
		arg.Status,
		arg.ScreenReason,
		arg.AiLabel,
		arg.AiScore,
		arg.ModelVersion,
		arg.FlagRule,
		arg.AiSentences,
		arg.ID,
	)
	var i ContentPost
	err := row.Scan(
		&i.ID,
		&i.ChannelID,
		&i.AuthorID,
		&i.Official,
		&i.Title,
		&i.Body,
		&i.SearchText,
		&i.Status,
		&i.Pinned,
		&i.Edited,
		&i.CommentCount,
		&i.OfficialReplied,
		&i.ScreenReason,
		&i.AiLabel,
		&i.AiScore,
		&i.ModelVersion,
		&i.FlagRule,
		&i.AiSentences,
		&i.NeedsRescan,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StatusChangedAt,
	)
	return i, err
}
